/* Penyelesaian penuh UKKM Set 1: Matematik & Sains (dimuat selepas kertas dihantar) */
(window.UKKM_SOL = window.UKKM_SOL || {})[1] = {"mat":["<h5>🧭 Faham soalan</h5><p>Jujukan bermula dengan 4, 9, 19 dan 39. Cari sebutan selepas 39.</p><h5>💡 Strategi</h5><p>Bandingkan sebutan berturutan untuk mengenal pasti aturan yang sama pada setiap langkah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>4 × 2 + 1 = 9.</li><li>9 × 2 + 1 = 19 dan 19 × 2 + 1 = 39.</li><li>Gunakan aturan itu sekali lagi: 39 × 2 + 1 = 79.</li><li>Jawapan: <b>A</b> (79).</li></ol><h5>🔍 Semak jawapan</h5><p>Beza sebutan ialah 5, 10, 20, 40. Oleh itu, 39 + 40 = 79.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (78): Lupa menambah 1 selepas mendarab 39 dengan 2 lalu mendapat 78.</li><li><b>C</b> (69): 69 hanya menambah 30 kepada 39, sedangkan beza sepatutnya berganda 5, 10, 20, 40; beza berikutnya ialah 40, bukan 30.</li><li><b>D</b> (59): Menambah beza terakhir, 20, sekali lagi lalu mendapat 59.</li></ul><h5>📌 Tip peperiksaan</h5><p>Semak aturan pada sekurang-kurangnya tiga pasangan sebelum memilih nombor berikutnya.</p>",
"<h5>🧭 Faham soalan</h5><p>Ada 45 kenderaan, semuanya motosikal atau kereta, dengan 130 roda. Cari beza bilangan motosikal dan kereta.</p><h5>💡 Strategi</h5><p>Anggap dahulu semua kenderaan ialah motosikal. Setiap kereta menggantikan motosikal dan menambah dua roda.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jika semuanya motosikal, bilangan roda = 45 × 2 = 90.</li><li>Roda tambahan = 130 − 90 = 40. Bilangan kereta = 40 ÷ 2 = 20.</li><li>Bilangan motosikal = 45 − 20 = 25. Beza = 25 − 20 = 5.</li><li>Jawapan: <b>A</b> (5).</li></ol><h5>🔍 Semak jawapan</h5><p>20 × 4 + 25 × 2 = 80 + 50 = 130 roda, dan 20 + 25 = 45 kenderaan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (10): 10 diperoleh daripada 40 ÷ 4, iaitu membahagi roda tambahan dengan 4; sepatutnya bahagi dengan 2 roda tambahan bagi setiap kereta, jadi beza sebenar ialah 5.</li><li><b>C</b> (20): 20 ialah bilangan kereta, belum lagi beza yang diminta.</li><li><b>D</b> (25): 25 ialah bilangan motosikal, belum lagi beza yang diminta.</li></ul><h5>📌 Tip peperiksaan</h5><p>Selepas memperoleh dua bilangan, baca semula sama ada soalan meminta jumlah, satu bilangan atau beza.</p>",
"<h5>🧭 Faham soalan</h5><p>Kasut berharga RM 84. Diskaun 25% diberi dahulu, kemudian cukai 10% dikenakan pada harga baharu.</p><h5>💡 Strategi</h5><p>Kira harga selepas diskaun, kemudian kenakan cukai pada harga itu kerana asas kedua-dua peratus berbeza.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Diskaun = 25% × RM 84 = RM 21. Harga selepas diskaun = RM 84 − RM 21 = RM 63.</li><li>Cukai = 10% × RM 63 = RM 6.30.</li><li>Jumlah dibayar = RM 63 + RM 6.30 = RM 69.30.</li><li>Jawapan: <b>B</b> (RM 69.30).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 84 × 0.75 × 1.10 = RM 69.30, sama dengan pengiraan dua langkah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 63.00): RM 63.00 ialah harga selepas diskaun sahaja; cukai tertinggal.</li><li><b>C</b> (RM 71.40): RM 71.40 terhasil daripada menolak 15% terus daripada RM 84, walhal cukai menggunakan harga diskaun.</li><li><b>D</b> (RM 92.40): RM 92.40 mengenakan cukai pada harga asal tanpa diskaun.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi perubahan peratus berturutan, darab faktor satu demi satu mengikut urutan yang diberi.</p>",
"<h5>🧭 Faham soalan</h5><p>Pencetak menghasilkan 18 halaman dalam 45 saat. Cari hasil dalam 4 minit pada kadar tetap.</p><h5>💡 Strategi</h5><p>Samakan unit masa terlebih dahulu, kemudian gunakan kadar halaman sesaat.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tukar masa: 4 minit = 4 × 60 = 240 saat.</li><li>Kadar cetakan = 18 ÷ 45 = 0.4 halaman sesaat.</li><li>Bilangan halaman = 0.4 × 240 = 96.</li><li>Jawapan: <b>B</b> (96).</li></ol><h5>🔍 Semak jawapan</h5><p>240 ÷ 45 = 5⅓ kumpulan masa; 18 × 5⅓ = 96 halaman.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (160): 160 diperoleh jika 45 saat tersilap ditukar kepada 0.45 minit: kadar menjadi 18 ÷ 0.45 = 40 halaman seminit, lalu 40 × 4 = 160; penukaran yang betul ialah 45 saat = 0.75 minit.</li><li><b>C</b> (90): 90 halaman bermaksud kadar 90 ÷ 240 = 0.375 halaman sesaat, tidak sepadan dengan kadar diberi.</li><li><b>D</b> (72): 72 datang daripada 18 × 4, iaitu menganggap 45 saat sebagai satu minit.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tulis unit pada setiap kadar supaya saat tidak tersalah dipadankan dengan minit.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual memberi markah enam murid. Markah Farah, 6, dibatalkan; cari min lima murid lain.</p><h5>💡 Strategi</h5><p>Min ialah jumlah markah dibahagi bilangan murid yang masih dikira. Baca lima markah yang tinggal daripada jadual.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah lima markah = 14 + 18 + 11 + 20 + 15 = 78.</li><li>Bilangan murid yang tinggal = 6 − 1 = 5.</li><li>Min baharu = 78 ÷ 5 = 15.6 markah.</li><li>Jawapan: <b>C</b> (15.6).</li></ol><h5>🔍 Semak jawapan</h5><p>Min asal ialah (78 + 6) ÷ 6 = 84 ÷ 6 = 14; membuang markah rendah sepatutnya menaikkan min.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (13.0): 13.0 datang daripada 78 ÷ 6, iaitu masih membahagi dengan enam murid.</li><li><b>B</b> (14.0): 14.0 ialah min asal yang masih memasukkan markah Farah.</li><li><b>D</b> (16.8): 16.8 datang daripada 84 ÷ 5, iaitu membuang murid tetapi tidak markahnya.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila data dikeluarkan, ubah kedua-dua jumlah nilai dan bilangan data.</p>",
"<h5>🧭 Faham soalan</h5><p>Laju tren ialah 72 km/j dan masa perjalanan 45 saat. Cari jarak dalam meter.</p><h5>💡 Strategi</h5><p>Gunakan jarak = laju × masa selepas menukar km/j kepada m/s.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>72 km = 72 000 m dan 1 jam = 3 600 saat.</li><li>Laju = 72 000 ÷ 3 600 = 20 m/s.</li><li>Jarak = 20 × 45 = 900 m.</li><li>Jawapan: <b>A</b> (900 m).</li></ol><h5>🔍 Semak jawapan</h5><p>45 saat ialah tiga perempat minit. Pada 20 m/s, jarak seminit 1 200 m; tiga perempatnya 900 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (1 200 m): 1 200 m ialah jarak dalam 60 saat, bukan 45 saat.</li><li><b>C</b> (3 240 m): 3 240 m datang daripada 72 × 45 tanpa menukar km/j kepada m/s.</li><li><b>D</b> (54 000 m): 54 000 m diperoleh jika 45 saat tersilap dianggap sebagai 45 minit: 72 × 45 ÷ 60 = 54 km = 54 000 m; masa yang betul hanya 45 saat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk menukar km/j kepada m/s, bahagi dengan 3.6.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual menunjukkan bilangan gol 0 hingga 4 dan kekerapan setiap bilangan. Cari mod serta julat gol.</p><h5>💡 Strategi</h5><p>Mod ialah nilai gol yang paling kerap. Julat ialah gol tertinggi tolak gol terendah, bukan beza kekerapan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada jadual, kekerapan terbesar ialah 8 perlawanan bagi 2 gol. Maka mod = 2 gol.</li><li>Bilangan gol terkecil = 0 dan terbesar = 4.</li><li>Julat = 4 − 0 = 4 gol.</li><li>Jawapan: <b>A</b> (Mod = 2, julat = 4).</li></ol><h5>🔍 Semak jawapan</h5><p>Kekerapan berjumlah 3 + 5 + 8 + 6 + 2 = 24 perlawanan seperti dinyatakan; mod dan julat dibaca pada baris gol.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Mod = 8, julat = 4): Mod 8 tersalah mengambil kekerapan tertinggi sebagai nilai gol.</li><li><b>C</b> (Mod = 2, julat = 6): Julat 6 tersalah mengira daripada kekerapan, walaupun mod 2 betul.</li><li><b>D</b> (Mod = 8, julat = 6): Kedua-dua mod 8 dan julat 6 menggunakan baris kekerapan sebagai data gol.</li></ul><h5>📌 Tip peperiksaan</h5><p>Kenal pasti baris nilai dan baris kekerapan sebelum mencari mod atau julat.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan tapak U dengan lebar luar 12 m, tinggi luar 8 m, serta takuk sedalam 5 m dan selebar 4 m. Cari seluruh perimeter.</p><h5>💡 Strategi</h5><p>Jejak setiap sisi sempadan U. Dua bahagian mendatar di atas bersama-sama 12 − 4 = 8 m.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah sisi mendatar = bawah 12 + dua bahagian atas 8 + dasar takuk 4 = 24 m.</li><li>Jumlah sisi tegak = dua sisi luar 2 × 8 + dua sisi takuk 2 × 5 = 16 + 10 = 26 m.</li><li>Perimeter = 24 + 26 = 50 m.</li><li>Jawapan: <b>C</b> (50 m).</li></ol><h5>🔍 Semak jawapan</h5><p>Perimeter segi empat luar = 2 × (12 + 8) = 40 m; takuk menambah dua sisi 5 m, jadi 40 + 10 = 50 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (36 m): 36 m terhasil jika perimeter luar 40 m ditolak dengan bukaan 4 m tanpa mengira sisi takuk.</li><li><b>B</b> (40 m): 40 m ialah perimeter segi empat luar; dua sisi takuk belum ditambah.</li><li><b>D</b> (54 m): 54 m terlebih 4 m kerana bahagian bukaan di atas takuk turut dikira sebagai sempadan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi takuk segi empat, garis mendatar yang diganti sama panjang; tambahan perimeter datang daripada dua sisi takuk.</p>",
"<h5>🧭 Faham soalan</h5><p>Tangga 2.5 m, kaki asalnya 0.7 m dari dinding. Hujung atas turun 0.4 m; cari jarak kaki yang baharu.</p><h5>💡 Strategi</h5><p>Tangga, dinding dan lantai membentuk segi tiga bersudut tegak. Gunakan Teorem Pythagoras dua kali.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tinggi asal = √(2.5² − 0.7²) = √(6.25 − 0.49) = √5.76 = 2.4 m.</li><li>Tinggi baharu = 2.4 − 0.4 = 2.0 m.</li><li>Jarak kaki baharu = √(2.5² − 2.0²) = √(6.25 − 4) = √2.25 = 1.5 m.</li><li>Jawapan: <b>D</b> (1.5 m).</li></ol><h5>🔍 Semak jawapan</h5><p>Jarak baharu 1.5 m melebihi 0.7 m, seperti dijangka apabila hujung tangga turun. 1.5² + 2.0² = 6.25 = 2.5².</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (0.7 m): 0.7 m ialah jarak asal; kaki tangga mesti bergerak keluar.</li><li><b>B</b> (0.8 m): 0.8 m ialah anjakan kaki, iaitu 1.5 − 0.7, bukan jarak baharu.</li><li><b>C</b> (1.1 m): 1.1 m datang daripada menambah penurunan 0.4 m pada jarak asal; pergerakan mendatar tidak semestinya sama.</li></ul><h5>📌 Tip peperiksaan</h5><p>Cari tinggi asal dahulu sebelum menggunakan tinggi selepas perubahan.</p>",
"<h5>🧭 Faham soalan</h5><p>Lima sahabat diberi hubungan lebih tinggi atau lebih rendah. Cari orang pada kedudukan ketiga dari atas.</p><h5>💡 Strategi</h5><p>Gabungkan semua perbandingan menjadi satu susunan menurun, kemudian kira kedudukan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Elisa lebih tinggi daripada Amir, dan Amir lebih tinggi daripada Badrul: Elisa > Amir > Badrul.</li><li>Badrul lebih tinggi daripada Chandra, dan Chandra lebih tinggi daripada Daniel.</li><li>Susunan lengkap ialah Elisa > Amir > Badrul > Chandra > Daniel. Orang ketiga tertinggi ialah Badrul.</li><li>Jawapan: <b>D</b> (Badrul).</li></ol><h5>🔍 Semak jawapan</h5><p>Badrul mempunyai dua orang di atasnya dan dua orang di bawahnya; kedudukannya tepat ketiga daripada lima.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Amir): Amir ialah orang kedua tertinggi.</li><li><b>B</b> (Chandra): Chandra ialah orang keempat tertinggi.</li><li><b>C</b> (Daniel): Daniel ialah orang kelima tertinggi.</li></ul><h5>📌 Tip peperiksaan</h5><p>Lukis satu rantai susunan supaya perkataan lebih tinggi dan lebih rendah tidak tertukar arah.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan 1, 2 dan 3 petak bersebelahan memerlukan 4, 7 dan 10 batang. Ada 100 batang; cari bilangan petak maksimum.</p><h5>💡 Strategi</h5><p>Petak pertama memerlukan empat batang. Setiap petak seterusnya berkongsi satu sisi lalu menambah tiga batang.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bagi n petak, bilangan batang = 4 + 3(n − 1) = 3n + 1.</li><li>Had batang: 3n + 1 ≤ 100, jadi 3n ≤ 99 dan n ≤ 33.</li><li>Untuk 33 petak, 3 × 33 + 1 = 100 batang. Maka maksimum 33 petak.</li><li>Jawapan: <b>C</b> (33).</li></ol><h5>🔍 Semak jawapan</h5><p>34 petak memerlukan 3 × 34 + 1 = 103 batang, melebihi 100.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (25): 25 terhasil daripada 100 ÷ 4, seolah-olah petak tidak berkongsi sisi.</li><li><b>B</b> (32): 32 petak hanya memakai 3 × 32 + 1 = 97 batang; masih boleh tambah satu petak.</li><li><b>D</b> (34): 34 memerlukan 103 batang, melebihi bekalan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam pola binaan, kira tambahan bagi setiap bentuk baharu, bukan kos bentuk pertama berulang kali.</p>",
"<h5>🧭 Faham soalan</h5><p>Umur ibu sekarang tiga kali umur anak. Dalam 12 tahun, umur ibu dua kali umur anak. Cari jumlah umur sekarang.</p><h5>💡 Strategi</h5><p>Wakilkan umur anak dengan x, kemudian bina persamaan daripada umur mereka 12 tahun lagi.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Umur anak sekarang = x; umur ibu sekarang = 3x.</li><li>Dalam 12 tahun: 3x + 12 = 2(x + 12) = 2x + 24.</li><li>Tolak 2x dan 12 pada kedua-dua belah: x = 12. Ibu = 3 × 12 = 36 tahun. Jumlah = 12 + 36 = 48 tahun.</li><li>Jawapan: <b>48 tahun</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Dalam 12 tahun, anak 24 tahun dan ibu 48 tahun; 48 = 2 × 24. Sekarang 36 = 3 × 12.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menambah 12 tahun kepada ibu sahaja mengabaikan bahawa anak juga bertambah umur.</li><li>Memberi 12 tahun sebagai jawapan mengambil umur anak, sedangkan soalan meminta jumlah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi masalah umur, tambah bilangan tahun yang sama pada umur setiap orang.</p>",
"<h5>🧭 Faham soalan</h5><p>Kos kipas RM 120. Harga tanda dinaikkan 50%, kemudian diskaun 20% diberi. Cari peratus untung berdasarkan kos.</p><h5>💡 Strategi</h5><p>Kira harga jual sebenar selepas dua perubahan, lalu bandingkan keuntungan dengan harga kos.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Harga tanda = RM 120 × 1.50 = RM 180.</li><li>Harga jual = RM 180 × 0.80 = RM 144. Untung = RM 144 − RM 120 = RM 24.</li><li>Peratus untung = RM 24 ÷ RM 120 × 100% = 20%.</li><li>Jawapan: <b>B</b> (20%).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 120 × 1.50 × 0.80 = RM 144, iaitu 120% daripada kos. Lebihan daripada 100% ialah 20%.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (10%): 10% daripada kos RM 120 hanyalah RM 12, sedangkan untung sebenar ialah RM 24; jadi peratusnya bukan 10%.</li><li><b>C</b> (24%): 24% mencampuradukkan untung RM 24 dengan peratusnya.</li><li><b>D</b> (30%): 30% datang daripada 50% − 20%; peratus itu dikenakan pada asas harga yang berbeza.</li></ul><h5>📌 Tip peperiksaan</h5><p>Peratus untung sentiasa menggunakan harga kos sebagai penyebut.</p>",
"<h5>🧭 Faham soalan</h5><p>RM 620 dibahagi antara Ain, Bob dan Chen. Nisbah Ain:Bob ialah 3:4, manakala Bob:Chen ialah 6:5. Cari bahagian Bob.</p><h5>💡 Strategi</h5><p>Samakan nombor bahagian Bob dalam kedua-dua nisbah supaya satu nisbah tiga orang boleh dibentuk.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Darab nisbah Ain:Bob dengan 3: 3:4 = 9:12. Darab nisbah Bob:Chen dengan 2: 6:5 = 12:10.</li><li>Nisbah Ain:Bob:Chen = 9:12:10. Jumlah bahagian = 9 + 12 + 10 = 31.</li><li>Nilai satu bahagian = RM 620 ÷ 31 = RM 20. Bob menerima 12 × RM 20 = RM 240.</li><li>Jawapan: <b>D</b> (RM 240.00).</li></ol><h5>🔍 Semak jawapan</h5><p>Ain menerima RM 180 dan Chen RM 200; RM 180 + RM 240 + RM 200 = RM 620.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 180.00): RM 180 ialah bahagian Ain, bukan Bob.</li><li><b>B</b> (RM 200.00): RM 200 ialah bahagian Chen, bukan Bob.</li><li><b>C</b> (RM 206.67): RM 206.67 hampir RM 620 ÷ 3; pembahagian sama rata mengabaikan nisbah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Samakan bahagian nama yang muncul dalam kedua-dua nisbah sebelum menjumlahkan bahagian.</p>",
"<h5>🧭 Faham soalan</h5><p>Carta palang memberi kekerapan 2, 4, 5, 8 dan 11 bagi 0 hingga 4 buku. Cari median bilangan buku.</p><h5>💡 Strategi</h5><p>Median ialah data di tengah selepas disusun. Gunakan kekerapan terkumpul untuk mencari kedudukan tengah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah murid = 2 + 4 + 5 + 8 + 11 = 30. Median ialah purata data ke-15 dan ke-16.</li><li>Kekerapan terkumpul bagi 0, 1, 2 dan 3 buku ialah 2, 6, 11 dan 19.</li><li>Data ke-12 hingga ke-19 semuanya 3 buku. Jadi data ke-15 dan ke-16 ialah 3; median = (3 + 3) ÷ 2 = 3.</li><li>Jawapan: <b>C</b> (3).</li></ol><h5>🔍 Semak jawapan</h5><p>Terdapat 11 murid membaca kurang daripada 3 buku dan 11 murid membaca 4 buku; nilai tengah jatuh pada 3 buku.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (2): 2 ialah nombor tengah pada paksi 0 hingga 4, bukan median mengikut kekerapan.</li><li><b>B</b> (2.73): 2.73 ialah min anggaran, diperoleh daripada 82 ÷ 30, bukan median.</li><li><b>D</b> (4): 4 ialah mod kerana mempunyai kekerapan 11, bukan nilai tengah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk bilangan data genap, cari dua kedudukan tengah sebelum mengambil puratanya.</p>",
"<h5>🧭 Faham soalan</h5><p>Setiap sudut pedalaman poligon sekata ialah 156°. Cari bilangan sisinya.</p><h5>💡 Strategi</h5><p>Sudut pedalaman dan sudut peluaran bersebelahan berjumlah 180°. Semua sudut peluaran poligon sekata berjumlah 360°.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Satu sudut peluaran = 180° − 156° = 24°.</li><li>Bilangan sisi = 360° ÷ 24° = 15.</li><li>Maka poligon sekata itu mempunyai 15 sisi.</li><li>Jawapan: <b>B</b> (15).</li></ol><h5>🔍 Semak jawapan</h5><p>Sudut pedalaman bagi 15 sisi ialah 180° − (360° ÷ 15) = 180° − 24° = 156°.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (24): 24 ialah saiz sudut peluaran dalam darjah, bukan bilangan sisi.</li><li><b>C</b> (13): 13 sisi memberi sudut peluaran 360° ÷ 13, bukan 24°.</li><li><b>D</b> (12): 12 sisi memberi sudut peluaran 30° dan sudut pedalaman 150°, bukan 156°.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi poligon sekata, cari sudut peluaran dahulu kerana jumlahnya sentiasa 360°.</p>",
"<h5>🧭 Faham soalan</h5><p>Seorang daripada Aiman, Ben dan Cheng memecahkan pasu. Tepat seorang bercakap benar. Cari pelakunya.</p><h5>💡 Strategi</h5><p>Uji setiap calon sebagai pemecah pasu dan kira bilangan pernyataan yang benar.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jika Aiman pelakunya: Aiman salah; Ben benar; Cheng benar. Dua orang benar, jadi kes ini ditolak.</li><li>Jika Cheng pelakunya: Aiman benar; Ben salah; Cheng benar. Dua orang benar, jadi kes ini ditolak.</li><li>Jika Ben pelakunya: Aiman benar; Ben salah; Cheng salah. Tepat seorang benar. Jadi Ben memecahkan pasu.</li><li>Jawapan: <b>B</b> (Ben).</li></ol><h5>🔍 Semak jawapan</h5><p>Kes Ben memenuhi kedua-dua syarat: hanya Ben memecahkan pasu dan hanya Aiman bercakap benar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Aiman): Jika Aiman pelakunya, Ben dan Cheng sama-sama benar; melanggar syarat seorang sahaja.</li><li><b>C</b> (Cheng): Jika Cheng pelakunya, Aiman dan Cheng sama-sama benar.</li><li><b>D</b> (Tidak dapat ditentukan): Pelaku dapat ditentukan secara tunggal melalui ujian tiga kes; bukan keadaan tidak tentu.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam teka-teki benar atau salah, uji semua kes dan kira, bukan meneka daripada satu ayat.</p>",
"<h5>🧭 Faham soalan</h5><p>Setiap sebutan mulai sebutan ketiga ialah jumlah dua sebutan sebelumnya. Sebutan ke-4 ialah 11 dan ke-7 ialah 47; cari ke-10.</p><h5>💡 Strategi</h5><p>Wakilkan sebutan ke-5 dengan x. Gunakan aturan jumlah untuk membina sebutan ke-6 dan ke-7.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Sebutan ke-5 = x; sebutan ke-6 = 11 + x. Maka sebutan ke-7 = x + (11 + x) = 11 + 2x.</li><li>11 + 2x = 47, jadi 2x = 36 dan x = 18. Sebutan ke-6 = 11 + 18 = 29.</li><li>Seterusnya sebutan ke-8 = 29 + 47 = 76; ke-9 = 47 + 76 = 123; ke-10 = 76 + 123 = 199.</li><li>Jawapan: <b>C</b> (199).</li></ol><h5>🔍 Semak jawapan</h5><p>Pada sebutan ke-7, 18 + 29 = 47 seperti diberi. Maka sambungan jujukan konsisten.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (83): 83 mengandaikan beza tetap, sedangkan aturan memerlukan tambah dua sebutan sebelumnya.</li><li><b>B</b> (123): 123 ialah sebutan ke-9, satu langkah sebelum yang ditanya.</li><li><b>D</b> (322): 322 = 123 + 199 ialah sebutan ke-11, satu langkah selepasnya.</li></ul><h5>📌 Tip peperiksaan</h5><p>Labelkan nombor kedudukan setiap sebutan untuk mengelakkan kesilapan satu langkah.</p>",
"<h5>🧭 Faham soalan</h5><p>Harga Januari RM 20. Februari naik 40%, Mac turun 25% daripada Februari dan April naik 10% daripada Mac. Cari perubahan berbanding Januari.</p><h5>💡 Strategi</h5><p>Kira harga bulan demi bulan kerana setiap peratus menggunakan harga bulan sebelumnya sebagai asas.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Februari = RM 20 × 1.40 = RM 28.</li><li>Mac = RM 28 × 0.75 = RM 21. April = RM 21 × 1.10 = RM 23.10.</li><li>Kenaikan dari Januari = RM 23.10 − RM 20 = RM 3.10. Peratus kenaikan = RM 3.10 ÷ RM 20 × 100% = 15.5%.</li><li>Jawapan: <b>B</b> (Naik 15.5%).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 20 × 1.40 × 0.75 × 1.10 = RM 23.10; harga akhir ialah 115.5% daripada harga awal, iaitu naik 15.5%.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Naik 5%): 5% ialah kenaikan hingga Mac sahaja: RM 21 berbanding RM 20.</li><li><b>C</b> (Naik 25%): 25% terhasil daripada 40% − 25% + 10%, walaupun asas setiap peratus berlainan.</li><li><b>D</b> (Naik 115.5%): 115.5% ialah harga akhir sebagai peratus harga awal, bukan peratus kenaikan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Gunakan faktor 1 tambah atau tolak kadar untuk perubahan harga berturutan.</p>",
"<h5>🧭 Faham soalan</h5><p>Piktograf menunjukkan simbol penuh dan separuh untuk Isnin hingga Khamis. Khamis menjual 45 pau lebih daripada Selasa. Cari jumlah empat hari.</p><h5>💡 Strategi</h5><p>Bezakan bilangan simbol Khamis dan Selasa untuk menentukan nilai satu simbol, kemudian jumlahkan semua simbol.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Selasa mempunyai 2½ simbol; Khamis 5½ simbol. Beza = 5½ − 2½ = 3 simbol.</li><li>Tiga simbol mewakili 45 pau, jadi satu simbol penuh n = 45 ÷ 3 = 15 pau.</li><li>Jumlah simbol = 4 + 2½ + 3 + 5½ = 15. Jumlah pau = 15 × 15 = 225.</li><li>Jawapan: <b>C</b> (225).</li></ol><h5>🔍 Semak jawapan</h5><p>Beza Khamis dan Selasa ialah 3 × 15 = 45 pau, sepadan dengan maklumat yang diberi. Jumlahnya pula 15 simbol × 15 pau = 225 pau.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (15): 15 ialah nilai satu simbol, bukan jumlah empat hari.</li><li><b>B</b> (210): 210 datang daripada mengabaikan dua simbol separuh: 14 × 15 = 210.</li><li><b>D</b> (240): 240 datang daripada mengira kedua-dua simbol separuh sebagai penuh: 16 × 15 = 240.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam piktograf, simbol separuh bernilai separuh kunci; jumlahkan semua simbol dahulu sebelum mendarab dengan nilai satu simbol.</p>",
"<h5>🧭 Faham soalan</h5><p>Enam murid duduk tiga pada setiap sisi meja. Boon dan Aqilah sesisi tetapi berjauhan; Erin berhadapan Boon. Cari orang di hadapan Aqilah.</p><h5>💡 Strategi</h5><p>Tetapkan tiga tempat pada setiap sisi. Gunakan syarat sesisi dan tidak bersebelahan untuk menentukan hujung dan tengah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Boon dan Aqilah mesti di dua hujung sisi yang sama. Satu tempat tengah pada sisi itu masih kosong.</li><li>Erin berada di sisi bertentangan, tepat di hadapan Boon. Danial dan Farid sesisi; dua tempat kosong pada sisi Erin untuk mereka. Maka Chitra mengisi tempat tengah di antara Boon dan Aqilah.</li><li>Farid tidak boleh bersebelahan dengan Erin, jadi Farid mesti di hujung satu lagi, iaitu di hadapan Aqilah. Danial di tengah.</li><li>Jawapan: <b>D</b> (Farid).</li></ol><h5>🔍 Semak jawapan</h5><p>Susunan dua sisi yang saling berhadapan ialah Boon–Chitra–Aqilah dan Erin–Danial–Farid. Semua syarat dipenuhi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Chitra): Chitra duduk sesisi dengan Aqilah, di tengah, bukan di hadapannya.</li><li><b>B</b> (Danial): Danial duduk di tengah dan berhadapan Chitra.</li><li><b>C</b> (Erin): Erin berhadapan Boon seperti dinyatakan, bukan Aqilah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Lukis petak tiga tempat pada dua sisi dan isi orang yang kedudukannya pasti dahulu.</p>",
"<h5>🧭 Faham soalan</h5><p>Cari digit sa bagi 7 dipangkatkan dengan 2026.</p><h5>💡 Strategi</h5><p>Perhatikan digit sa beberapa kuasa awal. Kitaran digit sa berulang setiap empat kuasa.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>7¹ berakhir dengan 7; 7² = 49 berakhir dengan 9; 7³ = 343 berakhir dengan 3; 7⁴ = 2401 berakhir dengan 1.</li><li>Kitarannya ialah 7, 9, 3, 1. Bahagi 2026 dengan 4: 2026 = 4 × 506 + 2.</li><li>Baki 2 bermaksud kedudukan kedua dalam kitaran, iaitu digit sa 9.</li><li>Jawapan: <b>D</b> (9).</li></ol><h5>🔍 Semak jawapan</h5><p>7⁶ juga berakhir dengan 9 kerana 6 berbaki 2 apabila dibahagi 4; pola yang sama berlaku pada 2026.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (1): 1 ialah digit sa pada kuasa yang habis dibahagi 4.</li><li><b>B</b> (3): 3 ialah digit sa pada kuasa berbaki 3 apabila dibahagi 4.</li><li><b>C</b> (7): 7 ialah digit sa pada kuasa berbaki 1, bukan baki 2.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk digit sa kuasa besar, cari panjang kitaran dan gunakan baki pembahagian eksponen.</p>",
"<h5>🧭 Faham soalan</h5><p>Hafiz menjawab 26 daripada 30 soalan. Betul mendapat 4 markah dan salah ditolak 1; jumlah markah 79. Cari bilangan betul.</p><h5>💡 Strategi</h5><p>Bina persamaan menggunakan hanya 26 soalan yang dijawab; empat soalan kosong menyumbang sifar.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Katakan b jawapan betul. Jawapan salah = 26 − b.</li><li>Markah = 4b − (26 − b) = 5b − 26. Jadi 5b − 26 = 79.</li><li>Tambah 26: 5b = 105. Bahagi 5: b = 21.</li><li>Jawapan: <b>C</b> (21).</li></ol><h5>🔍 Semak jawapan</h5><p>Jawapan salah = 26 − 21 = 5. Markah = 21 × 4 − 5 × 1 = 84 − 5 = 79.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (18): 18 betul bermakna 8 salah; markah 18 × 4 − 8 = 64, bukan 79.</li><li><b>B</b> (20): 20 betul bermakna 6 salah; markah 80 − 6 = 74.</li><li><b>D</b> (22): 22 betul bermakna 4 salah; markah 88 − 4 = 84.</li></ul><h5>📌 Tip peperiksaan</h5><p>Pisahkan soalan dijawab daripada jumlah soalan sebelum membina persamaan markah.</p>",
"<h5>🧭 Faham soalan</h5><p>RM 5 000 dilabur tiga tahun. P memberi faedah kompaun 4% setahun, Q faedah mudah 4.2% setahun. Bandingkan nilai akhir.</p><h5>💡 Strategi</h5><p>Bagi P, faedah ditambah pada baki setiap tahun. Bagi Q, faedah tahunan sentiasa berdasarkan modal asal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>P tahun pertama = 5 000 × 1.04 = RM 5 200; tahun kedua = 5 200 × 1.04 = RM 5 408; tahun ketiga = 5 408 × 1.04 = RM 5 624.32.</li><li>Faedah Q setahun = RM 5 000 × 0.042 = RM 210. Dalam tiga tahun = RM 210 × 3 = RM 630; nilai akhir Q = RM 5 630.</li><li>Beza = RM 5 630 − RM 5 624.32 = RM 5.68. Q lebih tinggi.</li><li>Jawapan: <b>A</b> (Q lebih tinggi sebanyak RM 5.68).</li></ol><h5>🔍 Semak jawapan</h5><p>P juga boleh dihitung sebagai 5 000 × 1.04³ = RM 5 624.32, kurang RM 5.68 daripada Q.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Q lebih tinggi sebanyak RM 30.00): RM 30 hanya beza faedah mudah 4.2% dan 4% sepanjang tiga tahun; ia mengabaikan kompaun P.</li><li><b>C</b> (P lebih tinggi sebanyak RM 5.68): P tidak lebih tinggi kerana RM 5 624.32 kurang daripada RM 5 630.</li><li><b>D</b> (Kedua-duanya sama): Kedua-duanya tidak sama; perbezaannya RM 5.68.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bandingkan nilai akhir dalam ringgit, bukan kadar tahunan sahaja.</p>",
"<h5>🧭 Faham soalan</h5><p>Tangki sudah separuh penuh. P mengisi penuh dalam 6 jam, Q dalam 4 jam dan R mengosongkan penuh dalam 12 jam. Cari minit untuk penuh.</p><h5>💡 Strategi</h5><p>Tambah kadar masuk P dan Q, tolak kadar keluar R, kemudian bahagi baki setengah tangki dengan kadar bersih.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kadar P = 1/6 tangki sejam; Q = 1/4 tangki sejam; R keluar = 1/12 tangki sejam.</li><li>Kadar bersih = 1/6 + 1/4 − 1/12 = 2/12 + 3/12 − 1/12 = 4/12 = 1/3 tangki sejam.</li><li>Baki tangki = 1 − 1/2 = 1/2. Masa = (1/2) ÷ (1/3) = 3/2 jam = 1.5 × 60 = 90 minit.</li><li>Jawapan: <b>90 minit</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Dalam 1.5 jam, kadar bersih mengisi 1.5 × 1/3 = 1/2 tangki; ditambah separuh asal menjadi satu tangki.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menggunakan satu tangki penuh sebagai baki akan menggandakan masa yang diperlukan.</li><li>Menambah kadar salur keluar R sebagai kadar masuk akan memberikan masa terlalu singkat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan kadar kerja, nyatakan bahagian kerja sejam sebelum menggabungkan kadar.</p>",
"<h5>🧭 Faham soalan</h5><p>Bestari mempunyai 30 murid dengan min 62. Bersama 20 murid Cemerlang, min 50 murid ialah 66. Cari min Cemerlang.</p><h5>💡 Strategi</h5><p>Tukar min kepada jumlah markah. Tolak jumlah Bestari daripada jumlah gabungan, kemudian bahagi dengan bilangan murid Cemerlang.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bilangan murid keseluruhan = 30 + 20 = 50. Jumlah markah keseluruhan = 50 × 66 = 3 300.</li><li>Jumlah markah Bestari = 30 × 62 = 1 860. Jumlah Cemerlang = 3 300 − 1 860 = 1 440.</li><li>Min Cemerlang = 1 440 ÷ 20 = 72.</li><li>Jawapan: <b>D</b> (72).</li></ol><h5>🔍 Semak jawapan</h5><p>(30 × 62 + 20 × 72) ÷ 50 = (1 860 + 1 440) ÷ 50 = 66, seperti diberi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (66): 66 ialah min gabungan, bukan min Cemerlang.</li><li><b>B</b> (67): 67 terlalu rendah; (30 × 62 + 20 × 67) ÷ 50 = 64.</li><li><b>C</b> (70): 70 datang daripada menganggap dua kelas sama besar: 2 × 66 − 62 = 70.</li></ul><h5>📌 Tip peperiksaan</h5><p>Min gabungan perlu ditimbang dengan bilangan data dalam setiap kumpulan.</p>",
"<h5>🧭 Faham soalan</h5><p>Titik A(−2, 1), B(4, 10) dan C(k, 16) sebaris. Cari koordinat x bagi C.</p><h5>💡 Strategi</h5><p>Pada garis lurus, kecerunan antara mana-mana dua titik sama. Gunakan A dan B untuk mendapatkan kecerunan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Perubahan y dari A ke B = 10 − 1 = 9; perubahan x = 4 − (−2) = 6. Kecerunan = 9 ÷ 6 = 1.5.</li><li>Dari B ke C, perubahan y = 16 − 10 = 6. Jadi 6 ÷ (k − 4) = 1.5.</li><li>Darab kedua-dua belah dengan k − 4: 6 = 1.5(k − 4). Maka k − 4 = 6 ÷ 1.5 = 4 dan k = 8.</li><li>Jawapan: <b>A</b> (8).</li></ol><h5>🔍 Semak jawapan</h5><p>Kecerunan BC = (16 − 10) ÷ (8 − 4) = 6 ÷ 4 = 1.5, sama dengan AB.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (10): 10 diperoleh jika pintasan-y tersilap dianggap 1: (16 − 1) ÷ 1.5 = 10; pintasan yang sebenar ialah 4.</li><li><b>C</b> (10.67): 10.67 hampir 16 ÷ 1.5 tetapi mengabaikan kedudukan B dan pintasan garis.</li><li><b>D</b> (20.5): 20.5 diperoleh jika kecerunan diterbalikkan kepada 6 ÷ 9 dari titik A: −2 + 15 ÷ (6 ÷ 9) = 20.5; kecerunan yang betul ialah 9 ÷ 6 = 1.5.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila mengira kecerunan, tolak koordinat mengikut urutan titik yang sama pada pengangka dan penyebut.</p>",
"<h5>🧭 Faham soalan</h5><p>Ada 70 syiling 10 sen, 20 sen dan 50 sen berjumlah RM 17. Bilangan 20 sen dua kali bilangan 10 sen. Cari bilangan 50 sen.</p><h5>💡 Strategi</h5><p>Wakilkan bilangan 10 sen dengan x. Tulis bilangan jenis lain dalam x dan gunakan jumlah nilai dalam sen.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Biarkan 10 sen = x keping, 20 sen = 2x keping. Bilangan 50 sen = 70 − x − 2x = 70 − 3x.</li><li>RM 17 = 1 700 sen. Maka 10x + 20(2x) + 50(70 − 3x) = 1 700.</li><li>Kembangkan: 10x + 40x + 3 500 − 150x = 1 700; 3 500 − 100x = 1 700; 100x = 1 800; x = 18. Jadi syiling 50 sen = 70 − 3 × 18 = 16 keping.</li><li>Jawapan: <b>16 keping</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Syiling ialah 18, 36 dan 16 keping: jumlah 70. Nilainya 180 + 720 + 800 = 1 700 sen.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menggunakan RM 17 sebagai 17 sen menyebabkan persamaan nilai tersalah unit.</li><li>Mengira 20 sen sama banyak dengan 10 sen mengabaikan syarat dua kali ganda.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tukar semua wang kepada sen sebelum membina persamaan syiling.</p>",
"<h5>🧭 Faham soalan</h5><p>Ada 300 ml larutan 20% bahan aktif. Larutan 35% ditambah sehingga campuran 25%. Cari isi padu yang ditambah.</p><h5>💡 Strategi</h5><p>Jumlah bahan aktif sebelum dan selepas bercampur sama. Wakilkan isi padu tambahan dengan x ml.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bahan aktif asal = 20% × 300 = 60 ml. Bahan aktif tambahan = 0.35x ml.</li><li>Jumlah isi padu = 300 + x ml. Persamaan: 60 + 0.35x = 0.25(300 + x) = 75 + 0.25x.</li><li>Tolak 0.25x dan 60: 0.10x = 15. Maka x = 15 ÷ 0.10 = 150 ml.</li><li>Jawapan: <b>A</b> (150 ml).</li></ol><h5>🔍 Semak jawapan</h5><p>Bahan aktif akhir = 60 + 0.35 × 150 = 112.5 ml; isi padu akhir 450 ml. 112.5 ÷ 450 = 0.25.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (300 ml): 300 ml memberi kepekatan (60 + 105) ÷ 600 = 27.5%, terlalu tinggi.</li><li><b>C</b> (450 ml): 450 ml ialah isi padu campuran akhir apabila 150 ml ditambah, bukan isi padu tambahan.</li><li><b>D</b> (600 ml): 600 ml memberi kepekatan (60 + 210) ÷ 900 = 30%, terlalu tinggi.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam campuran, samakan jumlah bahan aktif; jangan puratakan peratus tanpa mengambil kira isi padu.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan kolam bulat berdiameter 14 m dengan laluan selebar 3.5 m. Kos turap RM 30 setiap m². Cari kos laluan.</p><h5>💡 Strategi</h5><p>Cari luas bulatan luar dan tolak luas kolam. Kemudian darab luas laluan dengan kos seunit.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jejari kolam = 14 ÷ 2 = 7 m. Jejari luar = 7 + 3.5 = 10.5 m.</li><li>Luas laluan = (22 ÷ 7) × (10.5² − 7²) = (22 ÷ 7) × (110.25 − 49) = (22 ÷ 7) × 61.25 = 192.5 m².</li><li>Kos = 192.5 × RM 30 = RM 5 775.00.</li><li>Jawapan: <b>B</b> (RM 5 775.00).</li></ol><h5>🔍 Semak jawapan</h5><p>Luas luar = (22 ÷ 7) × 10.5² = 346.5 m²; luas kolam = (22 ÷ 7) × 7² = 154 m². Bezanya 192.5 m².</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 4 620.00): RM 4 620.00 datang daripada lilitan kolam 44 m × lebar 3.5 m × RM 30; lengkungan luar diabaikan.</li><li><b>C</b> (RM 10 395.00): RM 10 395.00 ialah kos keseluruhan bulatan luar, termasuk kolam.</li><li><b>D</b> (RM 23 100.00): RM 23 100.00 menggunakan diameter 21 m dan 14 m seolah-olah kedua-duanya jejari.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk laluan mengelilingi bulatan, tambah lebar pada jejari sebelum menolak dua luas.</p>"],
"sains":["<h5>🧠 Konsep utama</h5><p>Sel tumbuhan dan sel haiwan berkongsi beberapa struktur asas seperti nukleus, sitoplasma, membran sel dan mitokondria. Walau bagaimanapun, sel tumbuhan mempunyai beberapa komponen khusus yang tiada dalam sel haiwan, iaitu dinding sel, kloroplas dan vakuol pusat bersaiz besar. Kloroplas mengandungi pigmen hijau yang dipanggil klorofil. Klorofil berfungsi menyerap tenaga cahaya daripada Matahari untuk menjalankan proses fotosintesis bagi menghasilkan glukosa dan oksigen.</p><h5>✅ Mengapa jawapan C betul</h5><p>Kloroplas hanya terdapat dalam sel tumbuhan dan bertindak sebagai tapak fotosintesis, manakala sel haiwan tidak mempunyai kloroplas.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Mitokondria wujud dalam kedua-dua sel tumbuhan dan sel haiwan untuk menjana tenaga melalui respirasi sel.</li><li><b>B</b> — Nukleus terdapat dalam kedua-dua jenis sel bagi mengawal segala aktiviti sel dan menyimpan maklumat genetik DNA.</li><li><b>D</b> — Membran sel dimiliki oleh sel tumbuhan dan haiwan untuk mengawal pergerakan bahan keluar dan masuk ke dalam sel.</li></ul><h5>📌 Ingat</h5><p>Tiga struktur yang hanya ada pada sel tumbuhan ialah kloroplas (fotosintesis), dinding sel (mengekalkan bentuk), dan vakuol besar (menyimpan sap sel).</p>",
"<h5>🧠 Konsep utama</h5><p>Pencernaan kimia bermula di dalam rongga mulut melalui tindakan enzim pencernaan yang dirembeskan oleh kelenjar air liur. Air liur mengandungi enzim amilase liur yang memangkin penguraian kanji (karbohidrat kompleks yang tawar) kepada maltosa. Maltosa ialah sejenis gula disakarida ringkas yang mempunyai rasa manis secara semula jadi. Kunyahan berterusan memberi masa yang mencukupi untuk tindak balas hidrolisis ini berlaku dengan berkesan di dalam mulut.</p><h5>✅ Mengapa jawapan A betul</h5><p>Roti tawar kaya dengan kanji, dan enzim amilase liur menguraikan kanji tersebut kepada maltosa yang memberikan rasa manis.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Air liur tidak mengandungi protease; pencernaan protein hanya bermula di dalam perut melalui enzim pepsin.</li><li><b>C</b> — Asid hidroklorik dirembeskan oleh dinding perut untuk membunuh kuman dan mengaktifkan enzim, bukannya berada di mulut.</li><li><b>D</b> — Enzim lipase tidak aktif di dalam mulut; pencernaan lemak kepada asid lemak dan gliserol berlaku di dalam duodenum.</li></ul><h5>📌 Ingat</h5><p>Amilase liur hanya mencernakan kanji kepada maltosa, belum menjadi glukosa. Glukosa hanya dihasilkan oleh maltase di usus kecil.</p>",
"<h5>🧠 Konsep utama</h5><p>Mekanisme pernafasan manusia beroperasi mengikut prinsip perubahan isi padu dan tekanan udara di dalam rongga toraks. Semasa menarik nafas (tarikan nafas), otot diafragma mengecut lalu diafragma mendatar dan bergerak ke bawah. Pada masa yang sama, otot interkostal luar mengecut menyebabkan sangkar rusuk terangkat ke atas dan ke arah luar. Kedua-dua tindakan ini membesarkan rongga toraks, menyebabkan isi padu toraks bertambah dan tekanan udara di dalam peparu menurun di bawah tekanan atmosfera luar, membolehkan udara disedut masuk.</p><h5>✅ Mengapa jawapan D betul</h5><p>Semasa menarik nafas, diafragma mengecut dan mendatar, mengakibatkan isi padu rongga toraks bertambah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Diafragma hanya mengendur dan melengkung ke atas semasa menghembus nafas.</li><li><b>B</b> — Pengecutan diafragma membesarkan ruang toraks dan menambah isi padu, bukannya mengurangkannya.</li><li><b>C</b> — Keadaan diafragma mengendur melengkung ke atas dengan isi padu rongga toraks berkurang berlaku semasa hembusan nafas.</li></ul><h5>📌 Ingat</h5><p>Tarik nafas: otot mengecut → diafragma mendatar → isi padu toraks bertambah → tekanan peparu rendah → udara masuk.</p>",
"<h5>🧠 Konsep utama</h5><p>Yis menjalankan respirasi dan membebaskan karbon dioksida; bilangan gelembung per minit digunakan sebagai petunjuk kadar respirasi. Pemboleh ubah dimanipulasikan ialah suhu, manakala pemboleh ubah bergerak balas ialah bilangan gelembung per minit. Jenis dan kuantiti yis, kuantiti larutan gula serta tempoh pengiraan perlu dimalarkan. Apabila suhu meningkat, aktiviti enzim respirasi meningkat sehingga mencapai suhu yang paling sesuai dalam julat yang diuji. Suhu yang terlalu tinggi menyahaktifkan enzim dan menurunkan kadar respirasi.</p><h5>✅ Mengapa jawapan B betul</h5><p>Bilangan gelembung meningkat daripada 6 pada 20 °C kepada 25 pada 40 °C, kemudian turun kepada 11 pada 50 °C dan 0 pada 60 °C. Maka kadar respirasi meningkat hingga 40 °C dan menurun pada suhu lebih tinggi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kadar tidak terus meningkat; bacaan menurun selepas 40 °C.</li><li><b>C</b> — Bacaan berubah apabila suhu berubah, jadi suhu mempengaruhi kadar respirasi.</li><li><b>D</b> — Pada 60 °C tiada gelembung diperhatikan; aktiviti paling tinggi dalam jadual ialah pada 40 °C.</li></ul><h5>📌 Ingat</h5><p>Suhu terlalu tinggi boleh menyahaktifkan enzim. Tiada gelembung dalam tempoh pemerhatian tidak dengan sendirinya membuktikan semua yis telah mati.</p>",
"<h5>🧠 Konsep utama</h5><p>Sistem kumpulan darah ABO ditentukan oleh jenis antigen pada sel darah merah dan jenis antibodi di dalam serum plasma darah. Individu dengan kumpulan darah B memiliki antigen B pada sel darah merah dan antibodi anti-A dalam plasma. Sekiranya darah penderma mengandungi antigen A, antibodi anti-A penerima akan menyerang dan menggumpalkan sel darah merah tersebut (pengaglutinan), yang boleh membahayakan nyawa. Sel darah merah kumpulan O langsung tidak mempunyai antigen A mahupun antigen B pada permukaannya.</p><h5>✅ Mengapa jawapan C betul</h5><p>Darah kumpulan O tidak mempunyai sebarang antigen A atau B, jadi antibodi anti-A Encik Rahman tidak akan menggumpalkannya; kumpulan O ialah penderma universal.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Darah kumpulan A membawa antigen A yang akan digumpalkan oleh antibodi anti-A dalam plasma Encik Rahman.</li><li><b>B</b> — Darah kumpulan AB membawa antigen A dan antigen B, di mana antigen A akan mencetuskan pengaglutinan darah.</li><li><b>D</b> — Kedua-dua kumpulan darah A dan AB mengandungi antigen A yang berbahaya kepada penerima berdarah B.</li></ul><h5>📌 Ingat</h5><p>Kumpulan darah O ialah penderma universal kerana tiada antigen A dan B pada sel darah merahnya.</p>",
"<h5>🧠 Konsep utama</h5><p>Sistem saraf pusat manusia terdiri daripada otak dan saraf tunjang yang menyelaraskan gerak balas badan. Otak terbahagi kepada bahagian utama dengan peranan tersendiri: serebrum, serebelum dan medula oblongata. Serebelum terletak di bahagian belakang bawah otak dan berfungsi utama untuk memelihara keseimbangan badan, postur serta menyelaraskan koordinasi pergerakan otot rangka secara teratur. Kerosakan atau trauma pada serebelum mengakibatkan seseorang sukar mengimbangkan badan dan pergerakan menjadi kekok atau tidak terkoordinasi.</p><h5>✅ Mengapa jawapan D betul</h5><p>Pemain gimnastik kehilangan keseimbangan badan dan koordinasi pergerakan kerana bahagian serebelum mengalami kecederaan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Serebrum mengawal minda, kecerdasan, ingatan, pertimbangan serta semua tindakan terkawal sedar.</li><li><b>B</b> — Medula oblongata mengawal tindakan luar kawal autonomi seperti kadar denyutan jantung, peristalsis dan pernafasan.</li><li><b>C</b> — Saraf tunjang bertindak menghubungkan otak dengan saraf periferi serta mengawal tindakan refleks di bawah leher.</li></ul><h5>📌 Ingat</h5><p>Serebelum = pusat keseimbangan dan koordinasi otot. Serebrum = pusat pemikiran, deria dan tindakan sedar.</p>",
"<h5>🧠 Konsep utama</h5><p>Transpirasi ialah proses kehilangan air daripada tumbuhan dalam bentuk wap air ke atmosfera, terutamanya melalui liang stoma daun. Kadar transpirasi dipengaruhi oleh faktor persekitaran seperti kelajuan pergerakan udara (angin), suhu, keamatan cahaya dan kelembapan bandingan. Dalam penyiasatan ini, pemboleh ubah dimanipulasikan ialah pergerakan udara (kipas berpusing pada P berbanding tiada angin pada Q). Pemboleh ubah bergerak balas ialah kehilangan isi padu air (kadar transpirasi), manakala bilangan daun dan lapisan minyak dimalarkan. Pergerakan udara menyingkirkan wap air dari permukaan daun dengan pantas, mengekalkan kecerunan kepekatan yang curam untuk peresapan air keluar.</p><h5>✅ Mengapa jawapan A betul</h5><p>Keratan P di hadapan kipas kehilangan 12 mL air berbanding hanya 5 mL bagi Q, membuktikan bahawa pergerakan udara yang lebih laju meningkatkan kadar transpirasi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Suhu bukan pemboleh ubah yang diubah secara sengaja dalam eksperimen ini.</li><li><b>C</b> — Bilangan daun dimalarkan dengan menggunakan keratan yang serupa, bukannya pemboleh ubah manipulasi.</li><li><b>D</b> — Lapisan minyak hanya bertujuan menghalang air menyejat terus dari permukaan cecair silinder, bukan faktor transpirasi.</li></ul><h5>📌 Ingat</h5><p>Angin meniup wap air terkumpul di sekeliling stoma daun, mempercepatkan kadar kehilangan air melalui transpirasi.</p>",
"<h5>🧠 Konsep utama</h5><p>Kitar haid dikira bermula pada hari pertama haid. Ovulasi ialah pembebasan ovum daripada ovari. Dalam kitar 28 hari yang biasa, ovulasi dianggarkan berlaku sekitar hari ke-14, kira-kira 14 hari sebelum haid berikutnya. Masa sebenar boleh berubah antara individu dan antara kitar; tarikh ini hanyalah anggaran.</p><h5>✅ Mengapa jawapan B betul</h5><p>Jika 1 Mac ialah hari pertama, 14 Mac ialah hari ke-14. Oleh itu, 14 Mac ialah pilihan yang paling mungkin.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 5 Mac ialah hari ke-5, jauh lebih awal daripada anggaran hari ovulasi.</li><li><b>C</b> — 21 Mac ialah hari ke-21, lebih lewat daripada anggaran hari ke-14.</li><li><b>D</b> — 28 Mac ialah hari ke-28, iaitu penghujung kitar yang diandaikan.</li></ul><h5>📌 Ingat</h5><p>Kira hari pertama haid sebagai hari ke-1; hari ovulasi dalam kitar 28 hari ialah anggaran, bukan tarikh yang pasti.</p>",
"<h5>🧠 Konsep utama</h5><p>Malaria disebabkan oleh parasit protozoa Plasmodium. Nyamuk Anopheles betina yang dijangkiti menyebarkan parasit itu kepada manusia melalui gigitan. Dalam soalan ini, vektor ialah organisma yang membawa dan memindahkan patogen kepada manusia. Nyamuk betina menghisap darah untuk membantu perkembangan telurnya; sebab itulah nyamuk betina terlibat dalam penularan malaria.</p><h5>✅ Mengapa jawapan C betul</h5><p>Nyamuk Anopheles betina ialah vektor malaria kerana gigitannya boleh memindahkan Plasmodium kepada manusia.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Nyamuk Aedes menyebarkan penyakit seperti denggi, bukan malaria.</li><li><b>B</b> — Lalat rumah boleh mencemarkan makanan dengan patogen, tetapi bukan vektor malaria.</li><li><b>D</b> — Tikus boleh menjadi perumah takungan bakteria penyebab leptospirosis, tetapi bukan vektor malaria.</li></ul><h5>📌 Ingat</h5><p>Malaria: Plasmodium melalui nyamuk Anopheles betina. Denggi: virus melalui nyamuk Aedes.</p>",
"<h5>🧠 Konsep utama</h5><p>Siratan makanan menunjukkan hubungan pemakanan yang saling berkaitan antara beberapa rantai makanan dalam suatu ekosistem sawah padi. Berdasarkan rajah siratan makanan yang diberikan: padi dimakan oleh belalang dan tikus; belalang dimakan oleh katak; katak dimakan oleh ular; tikus dimakan oleh ular dan burung helang; ular pula dimakan oleh helang. Apabila populasi katak berkurang secara mendadak, tekanan pemangsaan terhadap belalang berkurang secara drastik. Oleh itu, populasi belalang akan bertambah. Pada masa yang sama, ular kehilangan sumber makanan utamanya (katak), lalu beralih memburu dan memakan lebih banyak tikus, menyebabkan populasi tikus berkurang.</p><h5>✅ Mengapa jawapan A betul</h5><p>Ketiadaan katak membolehkan belalang membiak dengan lebih banyak (bertambah), manakala ular meningkatkan pemangsaan ke atas tikus (berkurang).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Belalang tidak akan berkurang kerana pemangsa utamanya iaitu katak telah merosot.</li><li><b>C</b> — Populasi tikus tidak bertambah kerana ular memakan lebih banyak tikus sebagai sumber makanan alternatif.</li><li><b>D</b> — Belalang bertambah kerana pengurangan katak, bukannya berkurang.</li></ul><h5>📌 Ingat</h5><p>Penurunan populasi pemangsa menyebabkan populasi mangsanya bertambah, manakala pemangsa aras atas akan meningkatkan pemangsaan mangsa alternatif.</p>",
"<h5>🧠 Konsep utama</h5><p>Kekunci dikotomi ialah panduan klasifikasi biologi berasaskan siri pasangan ciri bertentangan yang membimbing pengenalpastian spesies secara berurutan. Haiwan vertebrata dibahagikan kepada lima kelas utama iaitu mamalia, burung, reptilia, amfibia dan ikan. Penyu tergolong dalam kelas reptilia. Ciri-ciri biologi reptilia termasuklah tidak berbulu roma, bernafas menggunakan peparu sepanjang hayat dewasa walaupun hidup di dalam air, poikilotermal (berdarah sejuk), dan mempunyai kulit kering yang dilitupi sisik atau plat keras bertanduk (karapas).</p><h5>✅ Mengapa jawapan D betul</h5><p>Menelusuri kekunci dikotomi:<br>Langkah 1: Penyu tidak berbulu roma → ikut 1(b) ke langkah 2.<br>Langkah 2: Penyu dewasa bernafas dengan peparu → ikut 2(b) ke langkah 3.<br>Langkah 3: Penyu mempunyai kulit kering bersisik keras → ikut 3(b) yang membawa kepada kumpulan Z.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kumpulan W mempunyai bulu roma, iaitu ciri unik bagi kelas mamalia.</li><li><b>B</b> — Kumpulan X bernafas menggunakan insang sepanjang hayat, iaitu ciri bagi kelas ikan.</li><li><b>C</b> — Kumpulan Y mempunyai kulit lembap tanpa sisik, iaitu ciri bagi kelas amfibia seperti katak.</li></ul><h5>📌 Ingat</h5><p>Sentiasa ikut pasangan ciri kekunci dikotomi satu per satu dari nombor 1 mengikut ciri sebenar organisma.</p>",
"<h5>🧠 Konsep utama</h5><p>Kawalan biologi ialah kaedah pengurusan perosak pertanian dengan memanfaatkan interaksi semula jadi seperti pemangsaan atau parasitisme antara organisma hidup. Burung hantu pungguk jelapang merupakan pemangsa semula jadi yang sangat aktif memburu tikus di ladang kelapa sawit. Kaedah ini mempunyai kelebihan ekologi yang besar berbanding racun perosak kimia sintetik kerana ia tidak mencemarkan tanah, sumber air atau merosakkan rantai makanan. Di samping itu, kawalan biologi tidak menghasilkan sisa toksik beracun atau menyebabkan rintangan racun pada perosak.</p><h5>✅ Mengapa jawapan A betul</h5><p>Membina sarang untuk burung hantu memburu tikus ialah kawalan biologi yang mesra alam dan tidak mencemarkan alam sekitar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Kaedah ini menggunakan pemangsa semula jadi, bukannya racun kimia perosak.</li><li><b>C</b> — Interaksi antara burung hantu dan tikus ialah pemangsaan (tikus dimakan), bukan mutualisme yang menguntungkan kedua-dua pihak.</li><li><b>D</b> — Interaksi ini bukan komensalisme kerana tikus dibunuh dan dirugikan sepenuhnya.</li></ul><h5>📌 Ingat</h5><p>Kawalan biologi menggunakan musuh semula jadi (pemangsa/parasit) untuk mengawal perosak tanpa mencemarkan alam sekitar.</p>",
"<h5>🧠 Konsep utama</h5><p>Jirim boleh wujud dalam tiga keadaan fizikal asas iaitu pepejal, cecair dan gas. Perubahan fasa jirim melibatkan proses penyerapan atau pembebasan tenaga haba. Kebanyakan bahan pepejal melebur menjadi cecair terlebih dahulu sebelum mendidih menjadi gas. Walau bagaimanapun, beberapa bahan seperti ais kering (karbon dioksida pepejal), iodin dan naftalena berubah secara langsung daripada keadaan pepejal kepada gas tanpa melalui fasa cecair. Proses penyerapan haba yang menukar pepejal terus kepada gas ini dinamakan pemejalwapan.</p><h5>✅ Mengapa jawapan B betul</h5><p>Ais kering mengecil dan bertukar terus menjadi gas karbon dioksida tanpa menghasilkan sebarang titisan cecair melalui proses pemejalwapan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Peleburan ialah perubahan daripada keadaan pepejal kepada cecair yang akan meninggalkan sisa basah cecair.</li><li><b>C</b> — Penyejatan ialah perubahan fasa daripada cecair kepada gas pada sebarang suhu di bawah takat didih.</li><li><b>D</b> — Pemeluwapan ialah proses pembebasan haba apabila gas bertukar menjadi cecair.</li></ul><h5>📌 Ingat</h5><p>Pepejal terus menjadi gas tanpa menjadi cecair = pemejalwapan. Contoh klasik: ais kering dan ubat gegat (naftalena).</p>",
"<h5>🧠 Konsep utama</h5><p>Graf pemanasan pepejal naftalena menunjukkan suhu meningkat sehingga mencapai takat leburnya iaitu 80 °C. Pada takat lebur (dari minit ke-4 hingga minit ke-8), graf menunjukkan garis mendatar di mana suhu kekal tidak berubah walaupun haba berterusan dibekalkan oleh pemanas. Sepanjang tempoh ini, pepejal dan cecair naftalena wujud bersama-sama. Tenaga haba yang diserap dikenali sebagai haba pendam pelakuran. Tenaga ini tidak meningkatkan tenaga kinetik zarah (suhu tidak naik), sebaliknya digunakan sepenuhnya untuk mengatasi dan memutuskan daya tarikan antara zarah-zarah pepejal supaya zarah dapat bergerak bebas sebagai cecair.</p><h5>✅ Mengapa jawapan A betul</h5><p>Suhu kekal malar pada 80 °C kerana tenaga haba yang diserap digunakan untuk mengatasi daya tarikan antara zarah pepejal semasa proses peleburan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Zarah naftalena sentiasa bergetar dan bergerak; semasa peleburan pergerakannya semakin bebas, bukan berhenti.</li><li><b>C</b> — Pemanas terus membekalkan haba tanpa henti sepanjang minit ke-4 hingga ke-8.</li><li><b>D</b> — Pada 80 °C naftalena sedang melebur menjadi cecair, bukannya mendidih menjadi gas (takat didih naftalena ialah 218 °C).</li></ul><h5>📌 Ingat</h5><p>Suhu kekal malar semasa peleburan kerana tenaga haba digunakan untuk mengatasi daya tarikan zarah, bukan menaikkan suhu.</p>",
"<h5>🧠 Konsep utama</h5><p>Campuran boleh diasingkan secara fizikal dengan memanfaatkan perbezaan sifat fizikal antara bahan juzuknya, seperti keterlarutan dan saiz zarah. Garam (natrium klorida) merupakan sebatian ion yang mudah larut di dalam air membentuk larutan akueus, manakala pasir (silika) tidak larut di dalam air. Apabila air ditambah kepada campuran, garam melarut manakala pasir kekal sebagai pepejal terampai. Proses penurasan menggunakan kertas turas akan menahan zarah pasir sebagai baki turasan, manakala larutan garam telus sebagai hasil turasan. Seterusnya, penyejatan hasil turasan akan menyingkirkan air ke udara dan meninggalkan hablur garam pepejal yang bersih.</p><h5>✅ Mengapa jawapan A betul</h5><p>Langkah melarutkan dalam air, menuras pasir, dan menyejatkan larutan garam mengasingkan kedua-dua bahan berasaskan keterlarutan garam dalam air.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Menuras campuran pepejal kering tidak dapat memisahkan garam daripada pasir kerana kedua-duanya tertahan pada kertas turas.</li><li><b>C</b> — Memanaskan campuran kering tidak memisahkan garam daripada pasir kerana takat lebur garam amat tinggi (801 °C) dan keduanya akan bercampur semula.</li><li><b>D</b> — Magnet tidak boleh digunakan kerana garam dan pasir merupakan bahan bukan magnet.</li></ul><h5>📌 Ingat</h5><p>Asingkan pepejal larut dan pepejal tak larut: larutkan dengan pelarut sesuai → turas baki → sejatkan hasil turasan.</p>",
"<h5>🧠 Konsep utama</h5><p>Air kapur ialah larutan kalsium hidroksida yang menjadi keruh apabila bertindak balas dengan karbon dioksida kerana mendakan kalsium karbonat terbentuk. Dalam eksperimen ini, jenis udara, iaitu udara hembusan atau udara sedutan, ialah pemboleh ubah dimanipulasikan. Masa yang diambil untuk air kapur menjadi keruh ialah pemboleh ubah bergerak balas. Isi padu dan kepekatan air kapur serta kadar aliran udara perlu dimalarkan supaya perbandingan adil. Udara hembusan mengandungi lebih banyak karbon dioksida kerana respirasi sel menghasilkan gas ini.</p><h5>✅ Mengapa jawapan C betul</h5><p>Air kapur X lebih cepat keruh daripada Y, menunjukkan udara hembusan mengandungi lebih banyak karbon dioksida daripada udara sedutan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Jika udara sedutan mengandungi lebih banyak karbon dioksida, air kapur Y sepatutnya lebih cepat keruh.</li><li><b>B</b> — Udara hembusan mengandungi kurang oksigen daripada udara sedutan; oksigen juga tidak mengeruhkan air kapur.</li><li><b>D</b> — Kekeruhan disebabkan oleh mendakan kalsium karbonat hasil tindak balas dengan karbon dioksida, bukan wap air.</li></ul><h5>📌 Ingat</h5><p>Lebih cepat air kapur keruh, lebih banyak karbon dioksida dalam udara yang dialirkan, jika keadaan ujian sama.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam konteks soalan ini, sengatan lebah dianggap berasid. Peneutralan berlaku apabila asid bertindak balas dengan bes, lalu mengurangkan keasidan. Soda penaik atau natrium bikarbonat membentuk larutan yang beralkali lemah apabila dicampur dengan air. Oleh itu, pesnya ialah pilihan yang paling sesuai antara empat bahan yang diberi. Keasidan air garam pula bergantung pada bahan terlarut dan tidak wajar dianggap sentiasa tepat pada pH 7.</p><h5>✅ Mengapa jawapan D betul</h5><p>Pes soda penaik bersifat beralkali lemah, jadi paling sesuai antara pilihan yang diberi untuk meneutralkan bahan berasid pada sengatan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Cuka mengandungi asid etanoik dan tidak meneutralkan asid.</li><li><b>B</b> — Jus limau nipis mengandungi asid sitrik dan tidak meneutralkan asid.</li><li><b>C</b> — Air garam biasa bukan alkali yang sesuai untuk meneutralkan asid; sifatnya juga tidak semestinya tepat pH 7.</li></ul><h5>📌 Ingat</h5><p>Untuk soalan peneutralan, padankan asid dengan bahan beralkali dan semak sifat setiap pilihan.</p>",
"<h5>🧠 Konsep utama</h5><p>Siri kereaktifan logam menyusun logam mengikut kecergasan tindak balas kimianya terhadap oksigen. Apabila serbuk logam dipanaskan bersama gas oksigen tulen, tindak balas pengoksidaan berlaku menghasilkan oksida logam dengan pembebasan tenaga haba dan cahaya yang terang. Kereaktifan relatif sesuatu logam dapat ditentukan melalui pemerhatian kualitatif terhadap keamatan nyalaan dan kepantasan pembakaran: logam yang lebih reaktif akan menyala dengan sangat terang dan pantas, manakala logam yang kurang reaktif hanya akan berbara malap secara perlahan.</p><h5>✅ Mengapa jawapan B betul</h5><p>Berdasarkan jadual, logam P menyala sangat terang (paling reaktif), logam R menyala terang (sederhana reaktif), dan logam Q hanya berbara malap (paling kurang reaktif); maka susunannya ialah P, R, Q.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Susunan P, Q, R salah kerana meletakkan Q sebelum R, sedangkan nyalaan terang R membuktikan R lebih reaktif daripada pembaraan malap Q.</li><li><b>C</b> — Susunan R, P, Q salah kerana P membebaskan nyalaan yang jauh lebih terang daripada R.</li><li><b>D</b> — Susunan Q, R, P menyusun logam daripada yang paling kurang reaktif kepada yang paling reaktif (terbalik).</li></ul><h5>📌 Ingat</h5><p>Semakin cergas dan terang tindak balas logam dengan oksigen, semakin tinggi kedudukannya dalam siri kereaktifan logam.</p>",
"<h5>🧠 Konsep utama</h5><p>Termokimia mengkaji pemindahan tenaga haba dalam tindak balas kimia dan proses fizikal seperti pelarutan garam. Tindak balas endotermik ialah proses yang menyerap tenaga haba daripada persekitaran ke dalam sistem tindak balas. Akibatnya, tenaga kinetik haba persekitaran berkurangan, menyebabkan suhu persekitaran (seperti air larutan dan dinding bekas bikar) jatuh dan berasa sejuk apabila disentuh. Sebaliknya, tindak balas eksotermik membebaskan haba ke persekitaran dan menyebabkan suhu persekitaran meningkat serta bekas terasa panas.</p><h5>✅ Mengapa jawapan D betul</h5><p>Pelarutan amonium nitrat dalam air merupakan proses endotermik kerana haba diserap daripada persekitaran sehingga dinding bikar menjadi sejuk.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Proses eksotermik membebaskan haba ke persekitaran dan akan menjadikan dinding bikar panas, bukan sejuk.</li><li><b>B</b> — Istilah eksotermik merujuk kepada pembebasan haba, bukan penyerapan haba daripada persekitaran.</li><li><b>C</b> — Tindak balas endotermik sentiasa menyerap haba dari persekitaran, bukannya membebaskan haba.</li></ul><h5>📌 Ingat</h5><p>Endotermik = serap haba dari persekitaran (suhu luar turun/sejuk). Eksotermik = bebas haba ke persekitaran (suhu luar naik/panas).</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam litar elektrik bersiri, semua perintang disambung secara sebaris dalam satu laluan arus tunggal yang sama. Rintangan berkesan keseluruhan litar bersiri, R, diperoleh dengan menjumlahkan semua rintangan individu: R = R₁ + R₂. Magnitud arus elektrik yang mengalir melalui setiap komponen dalam litar bersiri adalah sama nilainya pada mana-mana titik. Mengikut Hukum Ohm, hubungan antara beza keupayaan punca (V), arus elektrik (I) dan rintangan berkesan (R) diberikan oleh rumus I = V ÷ R.</p><h5>✅ Mengapa jawapan B betul</h5><p>Rintangan berkesan bersiri ialah R = 2 Ω + 4 Ω = 6 Ω. Bacaan ammeter dihitung menggunakan Hukum Ohm: I = V ÷ R = 6 V ÷ 6 Ω = 1.0 A.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Nilai 0.5 A diperoleh jika tersilap menganggap rintangan berkesan dua kali ganda lebih besar (6 ÷ 12).</li><li><b>C</b> — Nilai 1.5 A diperoleh sekiranya hanya mengira arus pada perintang 4 Ω secara berasingan (6 ÷ 4).</li><li><b>D</b> — Nilai 3.0 A diperoleh sekiranya hanya mengira arus pada perintang 2 Ω secara berasingan (6 ÷ 2).</li></ul><h5>📌 Ingat</h5><p>Litar bersiri: cari rintangan jumlah dahulu dengan menambah semua perintang (R = R₁ + R₂), kemudian guna rumus I = V ÷ R.</p>",
"<h5>🧠 Konsep utama</h5><p>Arus elektrik dalam gegelung menghasilkan medan magnet. Teras besi pada paku menguatkan medan itu kerana besi mudah dimagnetkan. Kekuatan elektromagnet juga bergantung pada arus dan bilangan lilitan gegelung. Jika bilangan lilitan ditambah sementara keadaan lain dikekalkan, kesan magnet pada paku biasanya bertambah dan lebih banyak klip kertas boleh ditarik.</p><h5>✅ Mengapa jawapan D betul</h5><p>Lebih banyak lilitan dawai pada paku menguatkan elektromagnet, lalu meningkatkan bilangan klip kertas yang dapat ditarik.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Rod kaca bukan teras feromagnet. Gegelung masih menghasilkan medan apabila berarus, tetapi kaca tidak menguatkannya seperti besi.</li><li><b>B</b> — Perintang tambahan yang disambung bersiri mengurangkan arus, lalu melemahkan elektromagnet.</li><li><b>C</b> — Menyongsangkan sambungan sel kering menukar arah medan dan kutub elektromagnet, bukan menambah kekuatannya.</li></ul><h5>📌 Ingat</h5><p>Tambahkan lilitan atau arus, atau gunakan teras besi lembut, untuk menguatkan elektromagnet.</p>",
"<h5>🧠 Konsep utama</h5><p>Jongkang-jongket ialah tuas kelas pertama dengan fulkrum di antara kedua-dua murid. Momen daya ialah daya didarab dengan jarak tegak dari fulkrum; unitnya N m. Untuk seimbang, momen di sebelah X mesti sama dengan momen di sebelah Y. Oleh sebab Y lebih berat, Y perlu duduk lebih dekat dengan fulkrum.</p><h5>✅ Mengapa jawapan B betul</h5><p>Momen X = 400 N × 1.5 m = 600 N m.<br>Momen Y = 600 N × d.<br>Untuk seimbang, 600 N m = 600 N × d.<br>d = 600 N m ÷ 600 N = 1.0 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 0.75 m ialah separuh jarak X, sedangkan nisbah berat Y kepada X ialah 600 ÷ 400 = 1.5, bukan 2.</li><li><b>C</b> — Pada 1.5 m, momen Y ialah 600 N × 1.5 m = 900 N m, melebihi 600 N m.</li><li><b>D</b> — 2.25 m terhasil jika nisbah berat disongsangkan: 600 ÷ 400 × 1.5 m. Momen Y ketika itu ialah 1350 N m.</li></ul><h5>📌 Ingat</h5><p>Semak unit momen, N m, sebelum membahagi dengan berat dalam N untuk mendapatkan jarak dalam m.</p>",
"<h5>🧠 Konsep utama</h5><p>Jirim pepejal seperti logam keluli pada rel kereta api tertakluk kepada prinsip pengembangan dan pengecutan terma. Apabila suhu persekitaran meningkat semasa cuaca panas terik atau akibat geseran roda kereta api, zarah-zarah logam menyerap haba dan bergetar lebih bertenaga. Ruang antara zarah bertambah lalu menyebabkan rel logam mengembang dan memanjang. Sekiranya tiada ruang celah disediakan pada sambungan rel, daya tolakan haba yang amat kuat antara rel bersebelahan akan membengkokkan rel tersebut.</p><h5>✅ Mengapa jawapan D betul</h5><p>Ruang kecil tersebut membolehkan rel logam mengembang dengan selamat semasa cuaca panas tanpa menolak satu sama lain dan melengkung.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Celah sambungan rel sebenarnya menghasilkan bunyi getaran apabila roda melintasinya, bukan mengurangkan bunyi.</li><li><b>B</b> — Saliran air hujan dialirkan oleh lapisan batu balast di bawah rel, bukannya melalui celah sambungan rel.</li><li><b>C</b> — Jurang kecil ini ditinggalkan demi prinsip keselamatan terma, bukannya untuk menjimatkan kos bahan besi.</li></ul><h5>📌 Ingat</h5><p>Pepejal mengembang apabila panas dan mengecut apabila sejuk. Celah pengembangan mencegah kerosakan struktur dan rel daripada melengkung.</p>",
"<h5>🧠 Konsep utama</h5><p>Cermin satah memantulkan cahaya mengikut hukum pantulan. Sinar pantulan sebenar tidak bertemu di belakang cermin. Apabila sinar pantulan dilanjutkan ke belakang secara bayangan, lanjutan itu seolah-olah bertemu di belakang cermin; sebab itu imejnya maya dan tidak dapat ditangkap pada skrin. Imej cermin satah tegak, sama saiz dengan objek dan mengalami songsang sisi. Jarak imej di belakang cermin sama dengan jarak objek di hadapan cermin.</p><h5>✅ Mengapa jawapan B betul</h5><p>Pilihan B menyatakan semua ciri utama imej cermin satah: maya, tegak, sama saiz dan songsang sisi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Imej bukan nyata dan tidak terbalik atas bawah; ia maya serta tegak.</li><li><b>C</b> — Imej memang maya dan tegak, tetapi saiznya sama dengan objek, bukan diperbesar.</li><li><b>D</b> — Imej bukan nyata atau dikecilkan; ia maya dan sama saiz dengan objek.</li></ul><h5>📌 Ingat</h5><p>Imej maya terbentuk daripada lanjutan sinar yang kelihatan bertemu; sinar sebenar tidak bertemu pada lokasi imej.</p>",
"<h5>🧠 Konsep utama</h5><p>Gelombang bunyi merambat melalui medium berzarah seperti air laut dan dipantulkan semula apabila mengenai permukaan pepejal seperti dasar laut untuk menghasilkan gema. Teknologi pantulan bunyi ultrasonik (sonar) digunakan untuk mengukur kedalaman laut atau mengesan objek dasar air. Gelombang bunyi bergerak dari pemancar kapal turun ke dasar laut dan melantun semula ke penerima di kapal, mencatatkan masa perjalanan dua hala (pergi dan balik). Oleh itu, kedalaman laut sehala (d) dihitung dengan membahagi dua jumlah jarak perjalanan gelombang: d = (laju bunyi × masa gema) ÷ 2.</p><h5>✅ Mengapa jawapan B betul</h5><p>Jumlah jarak pergi-balik = 1500 m s⁻¹ × 0.4 s = 600 m.<br>Kedalaman dasar laut sehala = 600 m ÷ 2 = 300 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Nilai 150 m terhasil jika tersilap membahagikan kedalaman sebenar dengan 2 sekali lagi.</li><li><b>C</b> — Nilai 600 m ialah jumlah jarak perjalanan pergi dan balik gelombang bunyi, terlupa membahagi dua untuk jarak sehala.</li><li><b>D</b> — Nilai 3750 m diperoleh daripada kesilapan membahagikan laju dengan masa (1500 ÷ 0.4) yang salah formulanya.</li></ul><h5>📌 Ingat</h5><p>Gema dan sonar melibatkan dua hala (pergi dan balik). Jangan lupa bahagikan jarak keseluruhan dengan 2: d = (v × t) ÷ 2.</p>",
"<h5>🧠 Konsep utama</h5><p>Tenaga elektrik ialah kuasa didarab dengan masa. Untuk mendapat unit kilowatt-jam (kWj), tukar kuasa daripada watt kepada kilowatt dan masa daripada minit kepada jam dahulu. Satu kilowatt bersamaan 1000 watt dan satu jam bersamaan 60 minit. Soalan meminta tenaga dalam sehari; pemanas digunakan 30 minit pada hari itu.</p><h5>✅ Mengapa jawapan A betul</h5><p>Kuasa = 2000 W ÷ 1000 = 2 kW.<br>Masa = 30 minit ÷ 60 = 0.5 jam.<br>Tenaga = 2 kW × 0.5 jam = 1 kWj.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — 2 kWj terhasil jika 2 kW didarab dengan 1 jam, sedangkan masa sebenar hanya 0.5 jam.</li><li><b>C</b> — 60 terhasil daripada 2 × 30 apabila 30 minit tersilap dianggap 30 jam.</li><li><b>D</b> — 2000 W × 0.5 jam = 1000 Wj, iaitu 1 kWj. Menulis 1000 kWj tersilap melabel Wj sebagai kWj.</li></ul><h5>📌 Ingat</h5><p>Semak unit akhir: 1000 Wj bersamaan 1 kWj.</p>",
"<h5>🧠 Konsep utama</h5><p>Sinaran alfa, beta dan gama berbeza dari segi kuasa penembusan. Zarah alfa mudah dihentikan oleh kertas, manakala zarah beta boleh menembusi kertas tetapi biasanya diserap oleh kepingan aluminium beberapa milimeter tebal. Sinar gama ialah gelombang elektromagnet yang jauh lebih menembusi. Aluminium setebal 5 mm tidak cukup untuk menyekatnya dengan berkesan; plumbum atau konkrit yang tebal digunakan untuk mengurangkan keamatannya dengan banyak. Ketebalan pelindung menentukan sejauh mana keamatan sinar gama berkurang.</p><h5>✅ Mengapa jawapan C betul</h5><p>Sinar gama boleh menembusi kepingan aluminium 5 mm dan dapat dikurangkan dengan kuat oleh blok plumbum tebal seperti yang dimaksudkan dalam soalan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Zarah alfa berkuasa penembusan rendah dan dihentikan oleh kertas.</li><li><b>B</b> — Zarah beta biasanya diserap oleh aluminium setebal beberapa milimeter.</li><li><b>D</b> — Kedua-dua zarah alfa dan beta tidak mempunyai kuasa penembusan yang diperlukan untuk menembusi aluminium 5 mm dalam perbandingan ini.</li></ul><h5>📌 Ingat</h5><p>Kuasa penembusan meningkat mengikut urutan alfa, beta, gama; pelindung tebal mengurangkan keamatan gama.</p>",
"<h5>🧠 Konsep utama</h5><p>Lapan buah planet dalam Sistem Suria dikelaskan kepada dua kumpulan utama mengikut kedudukannya terhadap jalur asteroid: planet dalaman dan planet luaran. Planet dalaman (planet terestrial) terdiri daripada Utarid, Zuhrah, Bumi dan Marikh yang berada lebih dekat dengan Matahari. Semua planet dalaman dicirikan oleh permukaan pejal yang berbatu dan mengandungi unsur logam silikat, berketumpatan tinggi serta bersaiz relatif kecil. Sebaliknya, planet luaran di luar jalur asteroid terbahagi kepada gergasi gas (Musytari dan Zuhal) serta gergasi ais (Uranus dan Neptun) yang sangat besar dan tiada permukaan batuan pejal.</p><h5>✅ Mengapa jawapan C betul</h5><p>Marikh ialah planet dalaman yang mempunyai permukaan pepejal berbatu dan kaya dengan sebatian besi oksida kemerahan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Musytari merupakan planet luaran terbesar yang terdiri daripada gas hidrogen dan helium tanpa permukaan berbatu.</li><li><b>B</b> — Zuhal ialah planet luaran gergasi gas yang dilingkari oleh gelang zarah ais dan debu.</li><li><b>D</b> — Neptun dikelaskan sebagai planet luaran gergasi ais yang sangat jauh dan sejuk.</li></ul><h5>📌 Ingat</h5><p>Planet dalaman berbatu: Utarid, Zuhrah, Bumi, Marikh. Planet luaran bergas/ais: Musytari, Zuhal, Uranus, Neptun.</p>",
"<h5>🧠 Konsep utama</h5><p>Angin suria membawa zarah bercas seperti elektron dan proton. Medan magnet Bumi memesongkan banyak zarah ini dan memandu sebahagiannya ke kawasan berhampiran kutub. Di atmosfera atas, zarah itu berlanggar dengan atom atau molekul oksigen dan nitrogen lalu memindahkan tenaga kepadanya. Apabila zarah gas tersebut kembali ke keadaan tenaga yang lebih rendah, cahaya dipancarkan. Cahaya inilah yang kelihatan sebagai aurora.</p><h5>✅ Mengapa jawapan A betul</h5><p>Pilihan A menerangkan sumber zarah bercas, peranan medan magnet Bumi dan perlanggaran dengan gas atmosfera yang menghasilkan aurora.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pantulan cahaya Matahari oleh ais tidak menghasilkan pancaran cahaya daripada gas atmosfera atas.</li><li><b>C</b> — Titisan air boleh menghasilkan pelangi melalui pembiasan, pantulan dalaman dan penyebaran cahaya Matahari; proses itu bukan punca aurora.</li><li><b>D</b> — Letusan gunung berapi membebaskan bahan dari kerak Bumi, bukan zarah angin suria yang menghasilkan aurora.</li></ul><h5>📌 Ingat</h5><p>Aurora melibatkan angin suria, medan magnet Bumi dan gas di atmosfera atas.</p>",
"<h5>🧠 Konsep utama</h5><p>Laluan akhir hayat bintang sangat bergantung pada jisim asalnya. Apabila hidrogen di teras bintang seperti Matahari semakin habis, lapisan luarnya mengembang dan bintang menjadi gergasi merah. Pada peringkat kemudian, lapisan luar dilepaskan dan membentuk nebula planet. Teras panas dan tumpat yang tertinggal menjadi kerdil putih, lalu menyejuk secara beransur-ansur. Bintang seperti Matahari tidak mempunyai jisim yang mencukupi untuk melalui letupan supernova.</p><h5>✅ Mengapa jawapan C betul</h5><p>Selepas gergasi merah membebaskan lapisan luarnya, teras yang tertinggal menjadi kerdil putih.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Lohong hitam boleh terbentuk daripada keruntuhan teras bintang yang jauh lebih berjisim selepas supernova, bukan bintang seperti Matahari.</li><li><b>B</b> — Bintang neutron ialah satu lagi kemungkinan sisa teras bintang besar selepas supernova.</li><li><b>D</b> — Supernova ialah peristiwa letupan, bukan jenis teras baki bagi bintang seperti Matahari.</li></ul><h5>📌 Ingat</h5><p>Bintang seperti Matahari: gergasi merah → nebula planet + kerdil putih.</p>"]};
